    from collections import Counter

    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    def runs(vals):
        result = []
        i = 0
        while i < len(vals):
            if vals[i] == bg:
                i += 1
                continue
            color = vals[i]
            j = i + 1
            while j < len(vals) and vals[j] == color:
                j += 1
            result.append((color, i, j - 1))
            i = j
        return result

    candidates = []
    # Pair matching colored runs on opposite edges.
    for orient in ("vertical", "horizontal"):
        if orient == "vertical":
            a, b = runs([grid[r][0] for r in range(h)]), runs([grid[r][w - 1] for r in range(h)])
        else:
            a, b = runs(grid[0]), runs(grid[h - 1])
        for ca, sa, ea in a:
            for cb, sb, eb in b:
                if ca == cb and ea - sa == eb - sb:
                    candidates.append((ea - sa + 1, orient, ca, (sa, ea), (sb, eb)))

    if not candidates:
        return out

    _, orient, wall, span_a, span_b = max(candidates)
    seeds = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
             if grid[r][c] != bg and grid[r][c] != wall]

    for r, c, color in seeds:
