            edge = 0 if side == 0 else w - 1
            step = -1 if edge < c else 1
            x = c + step
            while 0 <= x < w and grid[r][x] != wall:
                out[r][x] = color
                x += step
            # Matching ray at the corresponding position on the other edge.
            for x in range(w):
                if grid[mapped][x] != wall:
                    out[mapped][x] = color
        else:
            edge = 0 if side == 0 else h - 1
            step = -1 if edge < r else 1
            x = r + step
            while 0 <= x < h and grid[x][c] != wall:
                out[x][c] = color
                x += step
            for x in range(h):
                if grid[x][mapped] != wall:
                    out[x][mapped] = color

        out[r][c] = 4

    return out
